  var MON = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"], MN = {Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11};
  var DATE = "{d} {m} {y}", MONTH = "{m} {y}", REPORT = "Relatório diário do mercado {d}", UPDATED = "Atualizado: ";
